class Solution { void dfs(int node,vector<vector<int>>& graph,vector<int>& path,vector<vector<int>>& answer){if(node==(int)graph.size()-1){answer.push_back(path);return;}for(int next:graph[node]){path.push_back(next);dfs(next,graph,path,answer);path.pop_back();}}public:vector<vector<int>> allPathsSourceTarget(vector<vector<int>>& graph){vector<vector<int>> answer;vector<int> path{0};dfs(0,graph,path,answer);return answer;} };
